interface EvictionPolicy<K> { K pick(List<K> keys); }
final class LruPolicy<K> implements EvictionPolicy<K> {
    public K pick(List<K> keys) { return keys.get(0); }
}

final class Cache<K, V> {
    private final EvictionPolicy<K> policy;          // runtime policy, not a type parameter
    Cache(EvictionPolicy<K> policy) { this.policy = policy; }
    K victim(List<K> keys) { return policy.pick(keys); }
}
Cache<String, Integer> c = new Cache<>(new LruPolicy<>());
